/**
 * Warna & aturan edit status Request AYDA Motor — mengikuti workflow
 * "Request AYDA Unit" (field state = `workflow_state`).
 */

const STATE_COLOR = {
	Draft: 'gray',
	'Menunggu Approval': 'orange',
	'Proses Verifikasi Ops': 'blue',
	'Proses AYDA Finance': 'blue',
	'AYDA Done': 'green',
	Rejected: 'red',
	Cancelled: 'red',
}

const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
export function aydaPillClass(status) {
	return PILL[STATE_COLOR[status]] || PILL.gray
}

// Role yang boleh MENGEDIT dokumen per state (kolom Allow Edit workflow).
export const STATE_ALLOW_EDIT = {
	Draft: ['PIC Tarikan Coll'],
	'Menunggu Approval': ['Manager Coll'],
	'Proses Verifikasi Ops': ['Manager Ops'],
	'Proses AYDA Finance': ['Manager Finance'],
	'AYDA Done': ['Administrator'],
	Rejected: ['Administrator'],
	Cancelled: ['Administrator'],
}

// Filter Link `motor_tarikan` pada child unit: tipe Tarikan, status Stok Tebus,
// docstatus=1, dan cabang mengikuti cabang header. Pemanggil menahan pencarian
// hingga cabang dipilih.
export function motorTarikanFilters(cabang) {
	const f = [
		['tipe_motor', '=', 'Tarikan'],
		['status_unit', '=', 'Stok Tebus'],
		['docstatus', '=', 1],
	]
	if (cabang) f.push(['cabang', '=', cabang])
	return f
}
